<?php
namespace Cyberfort\AIRegister; defined( 'ABSPATH' ) || exit;
class Routes { public function init(): void { add_action( 'init', [ $this, 'register_rules' ] ); add_filter( 'query_vars', [ $this, 'vars' ] ); add_action( 'template_redirect', [ $this, 'render' ] ); } public function register_rules(): void { $slugs = array_unique( [ sanitize_title( get_option( 'cfair_base_slug', 'ai-register' ) ), 'mi-registrs' ] ); foreach ( $slugs as $slug ) { add_rewrite_rule( '^' . preg_quote( $slug, '/' ) . '/?$', 'index.php?cfair_view=register', 'top' ); add_rewrite_rule( '^' . preg_quote( $slug, '/' ) . '/([A-Za-z0-9_-]+)/?$', 'index.php?cfair_view=system&cfair_system_ref=$matches[1]', 'top' ); } } public function vars( array $vars ): array { return array_merge( $vars, [ 'cfair_view', 'cfair_system_ref', 'cfair_language' ] ); } public function render(): void { $view = get_query_var( 'cfair_view' ); if ( ! $view ) return; status_header( 200 ); nocache_headers(); get_header(); echo '<main class="cfair-route">'; echo 'register' === $view ? do_shortcode( '[cyberfort_ai_register]' ) : ( new Renderer() )->system( (string) get_query_var( 'cfair_system_ref' ) ); echo '</main>'; get_footer(); exit; } }
